test.describe("sign-in", () => {
  test.use({ receiptsPersona: "anonymous", receiptsFlags: {}, receiptsRedact: [] });

  test("Learner can sign in and sees their account menu", { tag: ["@auth"] }, async ({ page, receipts }) => {
    await test.step("1. Open the sign-in page", async () => {
      await receipts.chapter("Open the sign-in page", 1, 5);
      await page.goto(receipts.url("/signin"));
      await expect(page.getByRole("heading", { name: "Sign in" }), "role=heading[name=\"Sign in\"] is visible").toBeVisible();
    });
    await test.step("2. Enter credentials", async () => {
      await receipts.chapter("Enter credentials", 2, 5);
      await page.getByLabel("Email").fill("ada@acme.test");
    });
    await test.step("3. Fill", async () => {
      await receipts.chapter("Fill", 3, 5);
      await page.getByLabel("Password").fill("correct-horse");
      await receipts.capture("credentials-entered");
    });
    await test.step("4. Submit", async () => {
      await receipts.chapter("Submit", 4, 5);
      await page.getByRole("button", { name: "Sign in" }).click();
      await page.waitForURL((u) => receipts.urlMatches("**/courses", u.toString()));
      await expect.poll(() => receipts.urlMatches("**/courses", page.url()), "URL matches **/courses").toBe(true);
      await expect(page.getByTestId("account-menu"), "testId account-menu is visible").toBeVisible();
      await receipts.capture("signed-in");
    });
    await test.step("5. Profile details are redacted", async () => {
      await receipts.chapter("Profile details are redacted", 5, 5);
      // do: "Scroll the profile card into view" (compiled manual, step hash ebab83ac5e199cf7)
      await page.locator('.profile').scrollIntoViewIfNeeded();
      await expect(page.getByText("Your profile"), "text Your profile is visible").toBeVisible();
      expect(receipts.consoleErrors(), "0 console errors").toBeLessThanOrEqual(0);
      await receipts.capture("profile");
    });
  });
});
